lp-for-c.code:
#include <stdio.h>

int main(void) {
    int n;
    printf("Table of: ");
    scanf("%d", &n);
    for (int i = 1; i <= 10; i++) {
        printf("%d x %d = %d\n", n, i, n * i);
    }
    return 0;
}

lp-while-c.code:
#include <stdio.h>

int main(void) {
    int n, sum = 0;
    printf("Enter a number: ");
    scanf("%d", &n);
    while (n > 0) {
        sum = sum + n % 10;
        n = n / 10;
    }
    printf("Sum of digits = %d\n", sum);
    return 0;
}

